    """
    score: Numeric exam score from 0 to 100 inclusive. May include decimal values.
    rounding: Optional rounding method applied before grading. Accepted values: 'floor', 'round', 'ceil'. If omitted, no rounding is applied.
    returns: Letter grade: 'A', 'B', 'C', 'D', or 'F'.
    """
    if rounding == "floor":
        score = math.floor(score)
    elif rounding == "ceil":
        score = math.ceil(score)
    elif rounding == "round":
        score = round(score)
    # else: no rounding applied

    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    elif score >= 70:
        return "C"
    elif score >= 60:
        return "D"
    else:
        return "F"

