# Clarified spec:
# Convert a numeric exam score (0-100) to a letter grade: A is 90 and above, B is 80s, C is 70s, D is 60s, otherwise F. Scores can have decimals. Invalid rounding strings are ignored and no rounding is applied. Out-of-range scores are accepted and graded like any other number. The “round” method uses Python’s banker’s rounding (ties to even). Examples: 2.5, “Hello World” → F; -3.5 → F.
import datetime as _dt
import decimal as _decimal
import fractions as _fractions
import json
import math as _math

import pytest

from solution import score_to_letter_grade  # noqa: E402  (put your implementation in solution.py)

RAISES = "raises"


def canon(v, _depth=0):  # noqa: C901 - flat type dispatch is clearer here
    if _depth > 20:
        return "<deep>"
    if v is None:
        return "None"
    if isinstance(v, bool):
        return "True" if v else "False"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, (float, _decimal.Decimal, _fractions.Fraction)):
        try:
            f = float(v)
        except (OverflowError, ValueError):
            return str(v)
        if _math.isnan(f):
            return "nan"
        if _math.isinf(f):
            return "inf" if f > 0 else "-inf"
        r = round(f, 9)
        if r == int(r) and abs(r) < 1e15:
            return str(int(r))
        return repr(r)
    if isinstance(v, str):
        return repr(v)
    if isinstance(v, bytes):
        return repr(v)
    if isinstance(v, (_dt.datetime, _dt.date, _dt.time)):
        return v.isoformat()
    if isinstance(v, _dt.timedelta):
        return "timedelta(%r)" % v.total_seconds()
    if isinstance(v, (list, tuple)):
        return "[" + ", ".join(canon(x, _depth + 1) for x in v) + "]"
    if isinstance(v, (set, frozenset)):
        return "{" + ", ".join(sorted(canon(x, _depth + 1) for x in v)) + "}"
    if isinstance(v, dict):
        items = sorted((canon(k, _depth + 1), canon(x, _depth + 1)) for k, x in v.items())
        return "{" + ", ".join(f"{k}: {x}" for k, x in items) + "}"
    try:
        return f"<{type(v).__name__}:{str(v)[:80]}>"
    except Exception:  # noqa: BLE001
        return f"<{type(v).__name__}>"


CASES = [
    ('{"score": 0, "rounding": "floor"}', "'F'"),
    ('{"score": 89.5, "rounding": "round"}', "'A'"),
    ('{"score": 2.5, "rounding": "Hello World"}', "'F'"),
    ('{"score": -3.5, "rounding": ""}', "'F'"),
    ('{"score": 0.0, "rounding": "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"}', "'F'"),
    ('{"score": 99.99, "rounding": "  padded  "}', "'A'"),
    ('{"score": -3.5, "rounding": "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"}', "'F'"),
]


@pytest.mark.parametrize("args_json,expected", CASES)
def test_score_to_letter_grade(args_json, expected):
    args = json.loads(args_json)
    if expected == RAISES:
        with pytest.raises(Exception):
            score_to_letter_grade(**args)
    else:
        assert canon(score_to_letter_grade(**args)) == expected

